{
  "steps": [
    {
      "id": "s1",
      "desc": "Create a database migration to add the country_code column as nullable VARCHAR(2) with a default value of NULL.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Update the application code to write to both the legacy nullable column and a new temporary dual-write column or handle the nullable field gracefully during the transition phase.",
      "deps": [
        "s1"
      ]
    },
    {
      "id": "s3",
      "desc": "Deploy the updated application code to production to enable dual-write functionality for new signups and profile updates while maintaining backward compatibility.",
      "deps": [
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Launch a background backfill job to populate the country_code for all existing 50 million rows using the geolocation service in batches to avoid locking.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Verify that the backfill job has completed successfully and that the data integrity matches the geolocation service output for a sampled set of records.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Deploy a database migration to add a CHECK constraint enforcing the ISO-3166 alpha-2 format and alter the column to NOT NULL, ensuring all existing data complies.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Update the application code to remove dual-write logic and rely solely on the new schema for reading and writing country_code.",
      "deps": [
        "s6"
      ]
    },
    {
      "id": "s8",
      "desc": "Deploy the final application code update and execute automated tests to confirm end-to-end functionality of new signups and profile updates with the non-nullable column.",
      "deps": [
        "s7"
      ]
    }
  ]
}

{
  "steps": [
    {
      "id": "s1",
      "desc": "Update the application code to add the primary_email column to the database schema and configure dual-writes for both email and primary_email columns during the write phase.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Deploy the first application version (R1) that supports the new primary_email column alongside the existing email column with dual-write logic enabled.",
      "deps": [
        "s1"
      ]
    },
    {
      "id": "s3",
      "desc": "Execute a background backfill job to copy existing data from the email column to the primary_email column for all historical records.",
      "deps": [
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Update the application code to read from primary_email with a fallback to email using COALESCE to ensure data availability during the transition.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Deploy the second application version (R2) that implements the COALESCE read strategy to safely serve traffic from both columns.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Run comprehensive integration tests to verify that reads return correct data via the fallback mechanism and writes continue to update both columns.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Wait for a stabilization period to ensure all in-flight requests have completed and the system is stable with the new read logic.",
      "deps": [
        "s6"
      ]
    },
    {
      "id": "s8",
      "desc": "Deploy the third application version (R3) that exclusively reads from primary_email, treating the email column as legacy.",
      "deps": [
        "s7"
      ]
    },
    {
      "id": "s9",
      "desc": "Drop the old email column from the database schema after confirming that all application replicas are successfully running R3 and no reads depend on the old column.",
      "deps": [
        "s8"
      ]
    }
  ]
}

{
  "steps": [
    {
      "id": "s1",
      "desc": "Identify and log all orphan rows in the orders table where customer_id does not exist in the customers table.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Implement an application-layer guard to prevent new orphan records from being inserted into the orders table.",
      "deps": []
    },
    {
      "id": "s3",
      "desc": "Execute the cleanup policy to delete or reassign the identified orphan rows based on agreed business logic.",
      "deps": [
        "s1"
      ]
    },
    {
      "id": "s4",
      "desc": "Add the foreign key constraint to the orders table using the NOT VALID option to avoid a full-table scan and exclusive lock.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Validate the foreign key constraint in the background to ensure all existing data complies with the new rule.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Run integration tests to verify that the constraint exists, prevents new orphans, and handles ON DELETE RESTRICT correctly.",
      "deps": [
        "s5",
        "s2"
      ]
    }
  ]
}

{
  "steps": [
    {
      "id": "s1",
      "desc": "Run EXPLAIN ANALYZE on the target query to establish a baseline performance metric for the current unprocessed-events queue scan.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Execute CREATE INDEX CONCURRENTLY idx_events_created_at_unprocessed ON events (created_at) WHERE processed_at IS NULL to build the new partial index without blocking writes.",
      "deps": []
    },
    {
      "id": "s3",
      "desc": "Monitor pg_stat_progress_create_index to detect any stalled build and abort if the operation exceeds the acceptable time threshold, triggering manual recovery if necessary.",
      "deps": [
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Run ANALYZE on the events table to update statistics so the query planner recognizes the new index as a viable option.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Verify that the query planner consistently chooses the new partial index over the old btree index in EXPLAIN outputs for the target query.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Allow a mandatory bake period of 24 hours to ensure the new index is stable and serving the high-throughput workload without unexpected errors.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Execute DROP INDEX CONCURRENTLY idx_events_created_at to remove the old plain btree index now that the new index is fully adopted.",
      "deps": [
        "s6"
      ]
    },
    {
      "id": "s8",
      "desc": "Update the database runbook documentation to reflect the new partial index schema and the zero-downtime migration procedure.",
      "deps": [
        "s7"
      ]
    }
  ]
}
